package com.example.jsondemo.model;

import java.util.List;

import com.fasterxml.jackson.annotation.JsonProperty;

public record Person(
        @JsonProperty("name") String name,
        @JsonProperty("age") int age,
        @JsonProperty("email") String email,
        @JsonProperty("roles") List<String> roles) {
}

package com.example.jsondemo;

import java.util.List;

import com.example.jsondemo.model.Person;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;

/**
 * Parses JSON into objects/trees and serializes objects back to JSON.
 */
public class JsonService {

    private final ObjectMapper mapper;

    public JsonService() {
        this.mapper = new ObjectMapper()
                .registerModule(new JavaTimeModule())
                .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
    }

    /** Parse a JSON object into a {@link Person}. */
    public Person parsePerson(String json) throws JsonProcessingException {
        return mapper.readValue(json, Person.class);
    }

    /** Parse any JSON payload into a navigable tree. */
    public JsonNode parseTree(String json) throws JsonProcessingException {
        return mapper.readTree(json);
    }

    /** Serialize an object to a compact JSON string. */
    public String toJson(Object value) throws JsonProcessingException {
        return mapper.writeValueAsString(value);
    }

    /** Serialize an object to a pretty-printed JSON string. */
    public String toPrettyJson(Object value) throws JsonProcessingException {
        return mapper.writerWithDefaultPrettyPrinter().writeValueAsString(value);
    }

    public static void main(String[] args) throws JsonProcessingException {
        JsonService service = new JsonService();

        String input = """
                {
                  "name": "Ada Lovelace",
                  "age": 36,
                  "email": "ada@example.com",
                  "roles": ["admin", "engineer"]
                }
                """;

        Person person = service.parsePerson(input);
        System.out.println("Parsed:  " + person);
        System.out.println("Name:    " + person.name());
        System.out.println("Roles:   " + person.roles());

        Person generated = new Person("Grace Hopper", 85,
                "grace@example.com", List.of("engineer", "author"));
        System.out.println("Generated JSON:");
        System.out.println(service.toPrettyJson(generated));
    }
}

package com.example.jsondemo;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.List;

import org.junit.jupiter.api.Test;

import com.example.jsondemo.model.Person;
import com.fasterxml.jackson.databind.JsonNode;

class JsonServiceTest {

    private final JsonService service = new JsonService();

    @Test
    void parsesPersonFromJson() throws Exception {
        String json = """
                {"name":"Ada Lovelace","age":36,"email":"ada@example.com",
                 "roles":["admin","engineer"]}
                """;

        Person person = service.parsePerson(json);

        assertEquals("Ada Lovelace", person.name());
        assertEquals(36, person.age());
        assertEquals(List.of("admin", "engineer"), person.roles());
    }

    @Test
    void parsesNestedTree() throws Exception {
        JsonNode tree = service.parseTree("{\"user\":{\"id\":7,\"active\":true}}");

        assertEquals(7, tree.path("user").path("id").asInt());
        assertTrue(tree.path("user").path("active").asBoolean());
    }

    @Test
    void generatesJsonRoundTrip() throws Exception {
        Person original = new Person("Grace Hopper", 85, "grace@example.com", List.of("author"));
        String json = service.toJson(original);

        assertEquals(original, service.parsePerson(json));
    }
}
